 1→package com.cowave.search.outbound_adapter.proxy.brand
 2→
 3→import com.cowave.search.client.proxy_api.ProxyApiClient
 4→import com.cowave.search.domain.proxy.brand.BrandProjection
 5→import com.cowave.search.domain.proxy.brand.BrandProxyReader
 6→import org.springframework.stereotype.Component
 7→
 8→@Component
 9→class BrandProxyReaderImpl(
10→    private val client: ProxyApiClient,
11→) : BrandProxyReader {
12→    override fun getAllByIds(brandIds: List<Long>): List<BrandProjection> {
13→        val query =
14→            """
15→            query GetBrands(${'$'}ids: [Long!]!) {
16→                brands(input: { ids: ${'$'}ids }) {
17→                    items {
18→                        id
19→                        name
20→                    }
21→                }
22→            }
23→            """.trimIndent()
24→
25→        return client.query(
26→            query = query,
27→            variables = mapOf("ids" to brandIds),
28→            retrievePath = "brands.items",
29→            BrandProjection::class.java,
30→        )
31→    }
32→}

