 1→package com.cowave.shared.serialization
 2→
 3→import io.kotest.assertions.throwables.shouldNotThrowAny
 4→import io.kotest.assertions.throwables.shouldThrowAny
 5→import io.kotest.core.spec.style.FunSpec
 6→import io.kotest.matchers.shouldBe
 7→import kotlinx.serialization.Serializable
 8→
 9→class SerializableEntityTest : FunSpec ({
10→
11→    context("Serializable 객체의 직렬화 테스트") {
12→        val serializer = TestData.serializer()
13→
14→        test("기본적인 직렬화/역직렬화 테스트") {
15→            val entity = TestData(1, gender = Gender.MALE)
16→
17→            shouldNotThrowAny {
18→                val serialized = defaultJson.encodeToString(serializer, entity)
19→                val deserialized = defaultJson.decodeFromString(serializer, serialized)
20→
21→                deserialized.id shouldBe 1
22→                deserialized.name shouldBe null
23→                deserialized.gender shouldBe Gender.MALE
24→                deserialized.city shouldBe "Seoul"
25→            }
26→        }
27→
28→        test("ignoreUnknownKeys 테스트") {
29→            val serializedWithUnknownKeys = """{"id":1,"gender":"MALE","city":"Seoul","unknown1":null,"unknown2":2}"""
30→
31→            shouldNotThrowAny {
32→                defaultJson.decodeFromString(serializer, serializedWithUnknownKeys)
33→            }
34→        }
35→
36→        test("String to numeric 테스트") {
37→            val serialized = """{"id":"1","gender":"FEMALE","city":"Seoul"}"""
38→
39→            shouldNotThrowAny {
40→                val deserialized = defaultJson.decodeFromString(serializer, serialized)
41→                deserialized.id shouldBe 1
42→            }
43→        }
44→
45→        test("Numeric to String 혹은 없는 enum value는 역직렬화되지 않는다") {
46→            val serialized1 = """{"id":1,"gender":"FEMALE","city":100}"""
47→            val serialized2 = """{"id":1,"gender":"ANIMAL","city":"Seoul"}"""
48→
49→            shouldThrowAny {
50→                defaultJson.decodeFromString(serializer, serialized1)
51→                defaultJson.decodeFromString(serializer, serialized2)
52→            }
53→        }
54→    }
55→})
56→
57→enum class Gender { MALE, FEMALE }
58→
59→@Serializable
60→data class TestData(
61→    val id: Int,
62→    val name: String? = null,
63→    val gender: Gender,
64→    val city: String = "Seoul",
65→)
